package pods

import (
	"encoding/json"
	"maps"
	"os"
	"reflect"
	"strings"
	"testing"

	"github.com/wccomps/battleship/internal/config"
	"github.com/wccomps/battleship/internal/proxmox"
)

// testdata/parity.json is what proxmox-clone, the Python tool battleship
// replaced, does to made-up configs, generated by running its own code. These
// tests check battleship does the same, apart from deliberate differences:
//   - NICs keep their MAC and options other than tag (Python drops both, so
//     Proxmox picks a new MAC);
//   - drive options come out sorted, as Proxmox prints them;
//   - CD-ROM and cloud-init drives get no disk limits, and cloud-init drives
//     aren't ejected;
//   - team lists are sorted.
type parityCases struct {
	Network []struct {
		Name, Team string
		Interfaces int
		Config     map[string]string
		Put        map[string]string
	}
	Disks, CDROM []struct {
		Name   string
		Config map[string]string
		Put    map[string]string
	}
	Nodes []struct {
		Name     string
		Nodes    []string
		VMNodes  []string `json:"vm_nodes"`
		Teams    []string
		Assigned map[string]string
	}
	Teams []struct {
		Spec  string
		Teams []string
	}
	Clone []struct {
		Team         string
		TemplateVMID int `json:"template_vmid"`
		VMID         int
	}
}

func loadParity(t *testing.T) parityCases {
	t.Helper()
	b, err := os.ReadFile("testdata/parity.json")
	if err != nil {
		t.Fatal(err)
	}
	var c parityCases
	if err := json.Unmarshal(b, &c); err != nil {
		t.Fatal(err)
	}
	return c
}

// applied is cfg after a PUT of changes.
func applied(cfg, changes map[string]string) map[string]string {
	out := maps.Clone(cfg)
	maps.Copy(out, changes)
	return out
}

// sortedOptions rewrites every value's options in Proxmox's order.
func sortedOptions(cfg map[string]string) map[string]string {
	out := map[string]string{}
	for k, v := range cfg {
		out[k] = joinOptions(splitOptions(v))
	}
	return out
}

func TestParityNetwork(t *testing.T) {
	for _, c := range loadParity(t).Network {
		want := applied(c.Config, c.Put)
		for k, py := range c.Put {
			if !isNetKey(k) {
				continue
			}
			head, opts := splitOptions(c.Config[k])
			pyModel, pyOpts := splitOptions(py)
			if model, _, _ := strings.Cut(head, "="); model != pyModel {
				t.Errorf("%s: Python made %s a %s NIC, from %q", c.Name, k, pyModel, c.Config[k])
			}
			delete(opts, "tag")
			opts["bridge"] = pyOpts["bridge"]
			want[k] = joinOptions(head, opts)
		}
		got := applied(c.Config, NetworkChanges(config.Default().Network, c.Config, c.Team, c.Interfaces))
		if !reflect.DeepEqual(got, want) {
			t.Errorf("%s:\n got %v\nwant %v", c.Name, got, want)
		}
		if n := CountInterfaces(c.Config); n != c.Interfaces {
			t.Errorf("%s: CountInterfaces = %d, Python counted %d", c.Name, n, c.Interfaces)
		}
	}
}

func TestParityDiskLimits(t *testing.T) {
	for _, c := range loadParity(t).Disks {
		want := sortedOptions(applied(c.Config, c.Put))
		got := sortedOptions(applied(c.Config, DiskLimitChanges(c.Config, 300, 300)))
		if !reflect.DeepEqual(got, want) {
			t.Errorf("%s:\n got %v\nwant %v", c.Name, got, want)
		}
	}
}

func TestParityCDROM(t *testing.T) {
	for _, c := range loadParity(t).CDROM {
		want := applied(c.Config, c.Put)
		if got := applied(c.Config, CDROMChanges(c.Config)); !reflect.DeepEqual(got, want) {
			t.Errorf("%s:\n got %v\nwant %v", c.Name, got, want)
		}
	}
}

func TestParityNodes(t *testing.T) {
	n := NewNaming(config.Default().Naming)
	pod := make([]proxmox.VM, 10)
	for _, c := range loadParity(t).Nodes {
		var vms []proxmox.VM
		for _, node := range c.VMNodes {
			vms = append(vms, proxmox.VM{Node: node, Status: "running"})
		}
		if got := n.AssignNodes(c.Teams, c.Nodes, vms, pod); !reflect.DeepEqual(got, c.Assigned) {
			t.Errorf("%s: got %v, want %v", c.Name, got, c.Assigned)
		}
	}
}

func TestParityTeams(t *testing.T) {
	for _, c := range loadParity(t).Teams {
		if got, err := ParseTeams(c.Spec); err != nil || !reflect.DeepEqual(got, c.Teams) {
			t.Errorf("ParseTeams(%q) = %v, %v; want %v", c.Spec, got, err, c.Teams)
		}
	}
}

func TestParityCloneVMID(t *testing.T) {
	n := NewNaming(config.Default().Naming)
	for _, c := range loadParity(t).Clone {
		if got := n.CloneVMID(c.Team, c.TemplateVMID); got != c.VMID {
			t.Errorf("CloneVMID(%s, %d) = %d, want %d", c.Team, c.TemplateVMID, got, c.VMID)
		}
	}
}
